const lockDependencyGraphParentIssue = `-- name: LockDependencyGraphParentIssue :one

SELECT id, workspace_id, project_id
FROM issue
WHERE id = $1 AND workspace_id = $2
FOR UPDATE
`

type LockDependencyGraphParentIssueParams struct {
	ID          pgtype.UUID `json:"id"`
	WorkspaceID pgtype.UUID `json:"workspace_id"`
}

type LockDependencyGraphParentIssueRow struct {
	ID          pgtype.UUID `json:"id"`
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	ProjectID   pgtype.UUID `json:"project_id"`
}

// Dependency graph execution plans.
//
// These queries intentionally carry workspace_id on every graph lookup. The
// graph tables do not have foreign keys, so the workspace predicate is part
// of the application-level tenant boundary rather than an optional filter.
func (q *Queries) LockDependencyGraphParentIssue(ctx context.Context, arg LockDependencyGraphParentIssueParams) (LockDependencyGraphParentIssueRow, error) {
	row := q.db.QueryRow(ctx, lockDependencyGraphParentIssue, arg.ID, arg.WorkspaceID)
	var i LockDependencyGraphParentIssueRow
	err := row.Scan(&i.ID, &i.WorkspaceID, &i.ProjectID)
	return i, err
}

const markDependencyGraphAttentionForPrerequisite = `-- name: MarkDependencyGraphAttentionForPrerequisite :many
UPDATE dependency_graph_plan AS plan
SET attention_required = true,
    attention_reason = $3,
    updated_at = now()
WHERE plan.workspace_id = $1
  AND plan.status = 'active'
  AND EXISTS (
      SELECT 1
      FROM dependency_graph_edge edge
      WHERE edge.plan_id = plan.id
        AND edge.workspace_id = plan.workspace_id
        AND edge.from_issue_id = $2
  )
RETURNING plan.id
`

type MarkDependencyGraphAttentionForPrerequisiteParams struct {
	WorkspaceID     pgtype.UUID `json:"workspace_id"`
	FromIssueID     pgtype.UUID `json:"from_issue_id"`
	AttentionReason pgtype.Text `json:"attention_reason"`
}

// Failed/cancelled prerequisites never open a gate. They mark the active plan
// for operator attention so the graph remains auditable and fail-closed.
func (q *Queries) MarkDependencyGraphAttentionForPrerequisite(ctx context.Context, arg MarkDependencyGraphAttentionForPrerequisiteParams) ([]pgtype.UUID, error) {
	rows, err := q.db.Query(ctx, markDependencyGraphAttentionForPrerequisite, arg.WorkspaceID, arg.FromIssueID, arg.AttentionReason)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []pgtype.UUID{}
	for rows.Next() {
		var id pgtype.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const promoteReadyDependencyGraphDependents = `-- name: PromoteReadyDependencyGraphDependents :many
UPDATE issue AS target
SET status = 'todo',
    revision = revision + 1,
    last_activity_at = GREATEST(COALESCE(last_activity_at, updated_at), now()),
    updated_at = now()
WHERE target.workspace_id = $1
  AND issue_effective_status(target.workspace_id, target.status) = 'blocked'
  AND EXISTS (
      SELECT 1
      FROM dependency_graph_edge edge
      JOIN dependency_graph_plan plan
        ON plan.id = edge.plan_id
       AND plan.workspace_id = edge.workspace_id
       AND plan.status = 'active'
      WHERE edge.workspace_id = $1
        AND edge.from_issue_id = $2
        AND edge.to_issue_id = target.id
  )
  AND dependency_graph_issue_gate_open($1, target.id)
RETURNING target.id
`

type PromoteReadyDependencyGraphDependentsParams struct {
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	FromIssueID pgtype.UUID `json:"from_issue_id"`
}

